DELIMITER $$
--
-- Yordamlar
--
DROP PROCEDURE IF EXISTS `sp_tahmini_maliyet_hesapla`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_tahmini_maliyet_hesapla` (IN `p_tesis_turu` VARCHAR(50), IN `p_alan_m2` DECIMAL(10,2), OUT `p_toplam_maliyet` DECIMAL(15,2))   BEGIN
    DECLARE v_birim_maliyet DECIMAL(10,2);
    
    -- Parametre tablosundan güncel fiyatı çek
    IF p_tesis_turu = 'Okul' THEN
        SELECT deger INTO v_birim_maliyet FROM parametreler WHERE parametre_adi = 'maliyet_okul_m2';
    ELSEIF p_tesis_turu = 'Saglik' THEN
        SELECT deger INTO v_birim_maliyet FROM parametreler WHERE parametre_adi = 'maliyet_saglik_m2';
    ELSEIF p_tesis_turu = 'Park' THEN
        SELECT deger INTO v_birim_maliyet FROM parametreler WHERE parametre_adi = 'maliyet_park_m2';
    ELSE
        SET v_birim_maliyet = 5000; 
    END IF;

    SET p_toplam_maliyet = p_alan_m2 * v_birim_maliyet;
END$$

DELIMITER ;

